  for (let y = yb; y <= yb + 2; y++) put(g, x, y, 6, ...B.pane());
  put(g, x, yb - 1, 5, ...B.slab("smooth_quartz", "top"));
  put(g, x, yb + 3, 5, ...B.slab("smooth_quartz", "bottom"));
}

